/* Loaded after admin.js; existing authenticated API and modal helpers are reused. */
const imsState=document.createElement('div');imsState.className='ims-state';imsState.setAttribute('role','status');imsState.hidden=true;document.body.append(imsState);let imsTimer;
function operationalState(message,done=false){clearTimeout(imsTimer);imsState.textContent=message;imsState.hidden=false;if(done)imsTimer=setTimeout(()=>{imsState.hidden=true},2400);}
async function imsDocuments(v){const rows=await api('admin/ims/documents');if(tab!=='documents')return;const latest=new Set();v.innerHTML=`<div class="toolbar"><p>Controlled records · revisions · approvals · integrity checks</p><button class="btn" id="ims-new">New document</button></div>${table(['Document','Revision','Status','Review due','Actions'],rows.map(r=>{const first=!latest.has(r.document_id);latest.add(r.document_id);const overdue=r.status==='approved'&&r.review_due&&String(r.review_due).slice(0,10)<new Date().toISOString().slice(0,10);return `<tr><td><strong>${esc(r.code)}</strong><br>${esc(r.title)}<br><small>${esc(r.category)}</small></td><td>${r.revision}</td><td><span class="ims-status ${r.status}">${esc(r.status)}</span>${overdue?' <span class="ims-status overdue">Review overdue</span>':''}</td><td>${esc(r.review_due||'—')}</td><td><div class="ims-doc-actions"><a class="btn outline small" href="/api/admin/ims/versions/${r.id}/download">Download</a>${r.status==='draft'?`<button class="btn small" data-action="submit" data-id="${r.id}">Submit</button>`:''}${r.status==='review'?`<button class="btn small" data-action="approve" data-id="${r.id}">Approve</button><button class="btn outline small" data-action="reject" data-id="${r.id}">Reject</button>`:''}${first&&!['draft','review'].includes(r.status)?`<button class="btn outline small" data-revise="${r.document_id}">New revision</button>`:''}</div></td></tr>`;}))}`;v.querySelector('#ims-new').onclick=()=>imsUpload();v.querySelectorAll('[data-revise]').forEach(b=>b.onclick=()=>imsUpload(b.dataset.revise));v.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>imsDecision(b.dataset.id,b.dataset.action));}
function imsUpload(id){showModal(id?'New document revision':'Register controlled document',`<form id="ims-upload"><div class="ims-progress"><span></span></div><section class="ims-step active" data-step="1">${id?'<p>Upload a replacement revision. The approved version remains effective until approval.</p>':`${field('code','Document code','text','',true)}${field('title','Document title','text','',true)}${select('category','Category',['Corporate governance','Quality','Environment','Information security','Safety','Business continuity','Suppliers','Operations','ESG','Finance','Audit','Other'])}`}<button type="button" class="btn" id="ims-next">Continue →</button></section><section class="ims-step" data-step="2"><div class="field"><label for="ims-file">Document (PDF, DOCX, XLSX, TXT; max 5 MiB)</label><input id="ims-file" type="file" accept=".pdf,.docx,.xlsx,.txt" required></div><p class="ims-muted">Uploaded files are stored as drafts. Review and approval are separate recorded actions.</p><div class="ims-row"><button type="button" class="btn outline" id="ims-back">Back</button><button class="btn" type="submit">Save draft</button></div></section><div class="message hidden" id="form-notice" role="alert"></div></form>`);const f=document.querySelector('#ims-upload');const step=n=>{f.querySelectorAll('.ims-step').forEach(e=>e.classList.toggle('active',e.dataset.step===String(n)));f.querySelector('.ims-progress').classList.toggle('second',n===2);f.querySelector('.ims-step.active').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};f.querySelector('#ims-next').onclick=()=>{if([...f.querySelectorAll('[data-step="1"] input')].every(e=>e.reportValidity()))step(2);};f.querySelector('#ims-back').onclick=()=>step(1);f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('[type=submit]');btn.disabled=true;try{const file=f.querySelector('#ims-file').files[0];if(!file||file.size>5*1024*1024)throw Error('Choose a file up to 5 MiB');operationalState('Validating document…');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const body={...Object.fromEntries(new FormData(f)),filename:file.name,base64};await api(id?`admin/ims/documents/${id}/versions`:'admin/ims/documents','POST',body);closeModal();operationalState('Draft recorded. Integrity hash retained.',true);await load('documents');}catch(e){const n=f.querySelector('#form-notice');n.textContent=e.message;n.className='message error';operationalState('Document not saved.',true);}finally{btn.disabled=false;}};}
function imsDecision(id,action){showModal('Document '+action,`<form id="ims-decision">${action==='submit'?'<p>Submit this draft for review?</p>':area('note','Review decision and rationale')}${action==='approve'?field('review_due','Next review date','date','',true):''}<p class="ims-muted">This action will be recorded with your account and timestamp.</p>${formActions(action==='approve'?'Approve release':action==='reject'?'Reject revision':'Submit for review')}</form>`);const f=document.querySelector('#ims-decision');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{operationalState('Recording decision…');await api(`admin/ims/versions/${id}/action`,'POST',{action,...Object.fromEntries(new FormData(f))});closeModal();operationalState('Decision recorded.',true);await load('documents');}catch(e){const n=f.querySelector('#form-notice');n.textContent=e.message;n.className='message error';operationalState('Decision not recorded.',true);}finally{b.disabled=false;}};}
